import { createInterface } from 'readline';

// One shared line reader: piped input is buffered so multi-prompt flows don't
// lose lines. Call closePrompts() when done, or the open stdin keeps the
// process alive.
let _rl;
const _lines = [];
let _waiter = null;
let _closed = false;

function ensureReader() {
  if (_rl) return;
  _rl = createInterface({ input: process.stdin });
  _rl.on('line', (line) => {
    if (_waiter) {
      const w = _waiter;
      _waiter = null;
      w(line);
    } else {
      _lines.push(line);
    }
  });
  _rl.on('close', () => {
    _closed = true;
    if (_waiter) {
      const w = _waiter;
      _waiter = null;
      w(null); // EOF
    }
  });
}

function nextLine() {
  ensureReader();
  if (_lines.length) return Promise.resolve(_lines.shift());
  if (_closed) return Promise.resolve(null);
  return new Promise((resolve) => { _waiter = resolve; });
}

export function closePrompts() {
  if (_rl) {
    _rl.close();
    _rl = undefined;
  }
  _lines.length = 0;
  _waiter = null;
  _closed = false;
}

export async function ask(question) {
  process.stdout.write(question);
  const line = await nextLine();
  return line == null ? '' : line.trim();
}

// Anything but y/yes (including empty input) is false.
export async function confirm(question) {
  const answer = await ask(`${question} (y/N) `);
  return answer.toLowerCase() === 'y' || answer.toLowerCase() === 'yes';
}

/**
 * Ask for one of several single-letter choices; reprompts on invalid input.
 * @param {string} question
 * @param {string} choices  allowed letters, e.g. "ynaq"; the first is the default on Enter
 * @returns {Promise<string>} the chosen letter, lowercase
 */
export async function askChoice(question, choices) {
  const lower = choices.toLowerCase();
  const def = lower[0];
  const label = lower.split('').map((c, i) => (i === 0 ? c.toUpperCase() : c)).join('/');

  while (true) {
    const raw = await ask(`${question} (${label}) `);
    const input = raw.trim().toLowerCase();
    if (input === '') return def;
    if (input.length === 1 && lower.includes(input)) return input;
  }
}

// Returned by askLetter when input ends before a choice is made. Callers
// guarding destructive actions must treat it as "abort".
export const EOF = Symbol('prompt-eof');

/**
 * Like askChoice, with labels rendered as `[k]label`. Empty input picks an
 * option only if it is marked `default: true`; otherwise it reprompts.
 * @param {string} question
 * @param {Array<{key:string,label:string,default?:boolean}>} options
 * @returns the chosen key (lowercase), or EOF at end of input
 */
export async function askLetter(question, options) {
  const explicit = options.find((o) => o.default);
  const def = explicit ? explicit.key.toLowerCase() : null;
  // key 'y' + label 'yes' renders as `[y]es`; the default key is uppercase.
  const renderOpt = (o) => {
    const k = o.key.toLowerCase();
    const shown = o.default ? o.key.toUpperCase() : o.key;
    const lbl = o.label;
    return lbl.toLowerCase().startsWith(k)
      ? `[${shown}]${lbl.slice(1)}`
      : `[${shown}]${lbl}`;
  };
  const opts = options.map(renderOpt).join(' / ');
  const valid = new Set(options.map((o) => o.key.toLowerCase()));

  while (true) {
    process.stdout.write(`${question} ${opts} `);
    const line = await nextLine();
    if (line == null) return EOF;
    const input = line.trim().toLowerCase();
    if (input === '') {
      if (def) return def;
      continue;
    }
    if (input.length === 1 && valid.has(input)) return input;
  }
}

export async function waitForEnter(prompt = 'Press Enter to continue...') {
  process.stdout.write(prompt);
  await nextLine();
}

// Prompt for a secret without echoing it (raw mode on a TTY). On non-TTY
// stdin it reads one line from the shared reader and resolves null at EOF.
export function askPassword(question) {
  return new Promise((resolve, reject) => {
    const stdin = process.stdin;
    const stdout = process.stdout;

    stdout.write(question);

    if (!stdin.isTTY || typeof stdin.setRawMode !== 'function') {
      nextLine().then((line) => resolve(line == null ? null : line.trim()));
      return;
    }

    let input = '';
    stdin.setRawMode(true);
    stdin.resume();
    stdin.setEncoding('utf8');

    const cleanup = () => {
      stdin.setRawMode(false);
      stdin.pause();
      stdin.removeListener('data', onData);
    };

    const onData = (chunk) => {
      // A chunk may hold several characters (a pasted token).
      for (const ch of chunk) {
        if (ch === '\r' || ch === '\n') {
          cleanup();
          stdout.write('\n');
          resolve(input.trim());
          return;
        }
        if (ch === '\u0003') { // Ctrl-C
          cleanup();
          stdout.write('\n');
          process.exit(130);
        }
        if (ch === '\u007f' || ch === '\b') { // Backspace
          input = input.slice(0, -1);
          continue;
        }
        const code = ch.charCodeAt(0);
        if (code < 32) continue;
        input += ch;
      }
    };

    stdin.on('data', onData);
  });
}
